import os
from pathlib import Path
import subprocess
import time
import urllib.error
import urllib.request


def _command(target, config, *flags):
    return subprocess.run(['nginx', '-p', str(Path(target['prefix']).resolve()) + '/',
                           '-c', str(Path(config).resolve()), *flags],
                          stdin=subprocess.DEVNULL, capture_output=True, timeout=3)


def _probe(target, expected):
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    deadline = time.monotonic() + 2
    streak = 0
    while time.monotonic() < deadline:
        good = True
        for path, value in expected.items():
            try:
                with opener.open(target['url'] + path, timeout=.2) as response:
                    good = good and response.status == value[0] and response.read(1024).decode() == value[1]
            except (OSError, urllib.error.URLError):
                good = False
        streak = streak + 1 if good else 0
        if streak == 3:
            return True
        time.sleep(.03)
    return False


def _replace(path, content):
    path = Path(path)
    staged = path.with_name(path.name + '.release-tmp')
    staged.write_text(content, encoding='utf8')
    os.replace(staged, path)


def release(targets):
    snapshots = {}
    candidates = {}
    for target in targets:
        snapshots[target['id']] = Path(target['config']).read_text(encoding='utf8')
        candidate = Path(target['prefix']) / 'candidate.conf'
        candidate.write_text(target['candidate'], encoding='utf8')
        candidates[target['id']] = candidate
        if _command(target, candidate, '-t').returncode != 0:
            return {'status': 'rejected', 'failed': target['id']}
    touched = []
    failed = None
    try:
        for target in targets:
            touched.append(target)
            _replace(target['config'], target['candidate'])
            if _command(target, target['config'], '-s', 'reload').returncode != 0:
                raise RuntimeError(target['id'])
            if not _probe(target, target['new_checks']):
                raise RuntimeError(target['id'])
        return {'status': 'committed', 'failed': None}
    except (OSError, subprocess.SubprocessError, RuntimeError):
        failed = touched[-1]['id']
        recovery_ok = True
        for target in reversed(touched):
            try:
                _replace(target['config'], snapshots[target['id']])
                tested = _command(target, target['config'], '-t').returncode == 0
                reloaded = tested and _command(target, target['config'], '-s', 'reload').returncode == 0
                recovery_ok = _probe(target, target['old_checks']) and reloaded and recovery_ok
            except (OSError, subprocess.SubprocessError):
                recovery_ok = False
        return {'status': 'rolled_back' if recovery_ok else 'rollback_failed', 'failed': failed}

